package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching employee records by department and role
func searchHandler(w http.ResponseWriter, r *http.Request) {
	dept := r.URL.Query().Get("dept")
	role := r.URL.Query().Get("role")
	format := r.URL.Query().Get("fmt")

	if dept == "" {
		http.Error(w, "dept parameter required", http.StatusBadRequest)
		return
	}

	// Build query - role is optional filter
	var query string
	if role != "" {
		// NOTE: role is validated against allowed list
		allowedRoles := []string{"engineer", "manager", "director", "vp", "intern"}
		roleValid := false
		for _, ar := range allowedRoles {
			if strings.EqualFold(role, ar) {
				roleValid = true
				break
			}
		}
		if !roleValid {
			http.Error(w, "invalid role", http.StatusBadRequest)
			return
		}
		query = fmt.Sprintf("SELECT id, name, email, salary FROM employees WHERE department = '%s' AND role = '%s'", dept, role)
	} else {
		query = fmt.Sprintf("SELECT id, name, email, salary FROM employees WHERE department = '%s'", dept)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	if format == "csv" {
		w.Header().Set("Content-Type", "text/csv")
		fmt.Fprintf(w, "id,name,email,salary\n")
	}

	for rows.Next() {
		var id int
		var name, email string
		var salary float64
		if err := rows.Scan(&id, &name, &email, &salary); err != nil {
			continue
		}
		if format == "csv" {
			fmt.Fprintf(w, "%d,%s,%s,%.2f\n", id, name, email, salary)
		} else {
			fmt.Fprintf(w, "ID: %d | Name: %s | Email: %s | Salary: %.2f\n", id, name, email, salary)
		}
	}
}

// healthHandler for ALB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
